import {readSync} from 'node:fs';
import {parseRequestJSON} from './record-format-v2.js';
import {validateMutationRequest,constructMutation} from './recording-construction.js';
import {executeTargetedStore} from './record-store.js';
import {MUTATIONS,serializePrimary,primaryReceiptPreparer,id} from './recording-result.js';
import {RECORDING_SCHEMA} from './recording-contract.js';
import {stop,digest} from './record-store-files.js';
function input(){const chunks=[],buffer=Buffer.alloc(65536);let size=0,n;while((n=readSync(0,buffer,0,buffer.length,null))){size+=n;if(size>8388608)stop('limit-exceeded');chunks.push(Buffer.from(buffer.subarray(0,n)));}return Buffer.concat(chunks);}
function argumentsFor(argv){const operation=argv[0]==='batch'?'batch':`${argv[0]}.${argv[1]}`,start=operation==='batch'?1:2,flags=new Map(),duplicates=new Set(),positionals=[];let invalid=!MUTATIONS.includes(operation);for(let i=start;i<argv.length;i++){const k=argv[i];if(!k.startsWith('--')){positionals.push(k);continue;}if(flags.has(k)){invalid=true;duplicates.add(k);}flags.set(k,['--dry-run','--details','--help'].includes(k)?true:argv[i+1]!==undefined&&!argv[i+1].startsWith('--')?argv[++i]:null);}const help=flags.size===1&&flags.get('--help')===true&&!positionals.length&&!invalid;
 const needsId=['work.add','work.set','review.record','review.set','finding.add','finding.set','blocker.add','blocker.set','evidence.record','decision.record'].includes(operation);
 if(!help){for(const [k,v]of flags)if(!['--root','--change','--input','--format','--dry-run','--details',...(operation.startsWith('finding.')?['--review']:[])].includes(k)||v===null)invalid=true;if(!flags.get('--root')||!id(flags.get('--change'))||flags.get('--input')!=='-'||(flags.has('--format')&&!['json','text'].includes(flags.get('--format'))))invalid=true;if(needsId?positionals.length!==1||!id(positionals[0]):positionals.length!==0)invalid=true;if(operation.startsWith('finding.')&&!id(flags.get('--review')))invalid=true;}
 return{operation:MUTATIONS.includes(operation)?operation:null,flags,duplicates,positionals,invalid,help,format:flags.get('--format')==='json'?'json':'text'};
}
function expandedSchema(schema){if(Array.isArray(schema))return schema.map(expandedSchema);if(schema&&typeof schema==='object'){if(schema.$ref)return expandedSchema(RECORDING_SCHEMA.$defs[schema.$ref.split('/').at(-1)]);return Object.fromEntries(Object.entries(schema).map(([k,v])=>[k,expandedSchema(v)]));}return schema;}
export function executeRecordingMutationCli(argv,options={}){
 const args=argumentsFor(argv),{flags,operation,format}=args;let changeId=!args.duplicates.has('--change')&&id(flags.get('--change'))?flags.get('--change'):undefined;
 try{
  if(args.invalid)stop('invalid-input');
  if(args.help){const schema=RECORDING_SCHEMA.$defs[(['review.set','verify.set'].includes(operation)?'v3':'v2')+'-operation-'+operation];return{result:null,json:'',human:`${operation}: record explicit decisions (storage-only).\nRequires --root PATH --change ID --input -${args.operation.startsWith('finding.')?' and ID --review REVIEW-ID':''}. Optional --dry-run, --details, --format json|text.\nEnvelope: schema_version=1, interface=targeted-recording-v1, contract, change_id, expected_revision, reads, ${operation==='batch'?'operations (1..64, excluding change.create)':'operation'}.\nExample: rigorloop ${operation.replace('.', ' ')}${['work.add','work.set','review.record','blocker.add','blocker.set','evidence.record','decision.record'].includes(operation)?' entry-id':operation.startsWith('finding.')?' finding-id --review review-id':''} --root ROOT --change CHANGE --input - --format json\n${['review.record','evidence.record','decision.record','verify.record'].includes(operation)?'New supporting records require explicit applicability; existing declarations are preserved when omitted.\n':''}${['finding.add','blocker.add'].includes(operation)?'rigorloop-records-v2 requires basis as shown below; origin is constructed from the explicit basis.\n':operation==='change.create'?'Primary creation requires rigorloop-records-v2; existing roots are never converted.\n':''}${schema?JSON.stringify(expandedSchema(schema))+'\n':'Each batch element uses its command schema; see per-command help.\n'}`,exitCode:0,format};}
  changeId=flags.get('--change');const request=parseRequestJSON(options.input??(options.readInput??input)());validateMutationRequest(request,operation==='batch');if(operation==='change.create'&&request.contract==='rigorloop-records-v3')stop('unsupported-contract');if(request.change_id!==changeId)stop('invalid-input');if(operation!=='batch'&&(request.operation.op!==operation||(args.positionals.length&&request.operation.target.id!==args.positionals[0])||(flags.has('--review')&&request.operation.target.review!==flags.get('--review'))))stop('invalid-input');
  const output=executeTargetedStore({root:flags.get('--root'),changeId,request,preview:flags.has('--dry-run'),construct:constructMutation,prepare:built=>primaryReceiptPreparer({operation,changeId,changed:built.changed,...(flags.has('--details')?{details:{files:built.request.writes.map(w=>({path:w.path,identity:digest(w.content)})),effects:built.effects}}:{})})},options);
  return{...output,format};
 }catch(e){const code=e.recordStoreCode??(e.code?'io-failure':String(e.message).includes('limit')?'limit-exceeded':'invalid-input'),status=({'identity-conflict':'conflict','store-busy':'busy','recovery-needed':'recovery-required'}[code]??'rejected');const error={code,message:`Record: ${code}.`,...(e.field?{field:e.field}:{}),...(Number.isInteger(e.operation_index)?{operation_index:e.operation_index}:{})};return{...serializePrimary({schema_version:['review.set','verify.set'].includes(operation)?3:(e.responseVersion??2),operation,status,claim:'storage-only',...(changeId?{change_id:changeId}:{}),errors:[error],...(e.revision?{revision:e.revision}:{}),...(e.observation_summary?{observation_summary:e.observation_summary}:{}),...(status==='recovery-required'&&e.transaction?{transaction:e.transaction}:{})}),format};}
}
